import json
store = {}  # 정규화 캐시: "타입:id" -> 필드

def normalize(o):
    if isinstance(o, list):
        return [normalize(x) for x in o]
    if isinstance(o, dict):
        out = {k: normalize(v) for k, v in o.items()}
        if "__typename" in out and "id" in out:
            key = f'{out["__typename"]}:{out["id"]}'
            store[key] = {**store.get(key, {}), **out}
            return {"__ref": key}
        return out
    return o

# 탐색 목록 응답
normalize({"teachers": [{"__typename": "Teacher", "id": "t1", "name": "김선생", "reviewCount": 3}]})
# 프로필 화면 응답 — 같은 선생님, 후기 수가 늘었다
normalize({"teacher": {"__typename": "Teacher", "id": "t1", "reviewCount": 4, "intro": "핸드드립 10년"}})
print(json.dumps(store, ensure_ascii=False))

MIN = {"share": "24.10.0", "calendar": "25.3.0"}  # 기능별 최소 앱 버전(가상 값)

def ver(s):
    return tuple(int(x) for x in s.split("."))

def call_native(app, feature, fallback):
    if feature not in MIN or ver(app) < ver(MIN[feature]):
        return f"웹 대안: {fallback}"
    return f"네이티브 {feature}"

for v in ["24.9.2", "25.1.0", "25.4.1"]:
    print(v, "|", call_native(v, "share", "링크 복사"), "|", call_native(v, "calendar", "일정 문구 복사"))
